// Writes lib/src/model_tiers_table.dart from ../catalog/model-tiers.json, so
// the SDK carries the same table the catalog publishes. A test fails if the
// two ever differ.
// ignore_for_file: avoid_print
import 'dart:io';

void main() {
  final json = File('../catalog/model-tiers.json').readAsStringSync().trim();
  if (json.contains("'''")) throw StateError('table contains triple quotes');
  File('lib/src/model_tiers_table.dart').writeAsStringSync(
      '''// Generated by tool/sync_model_tiers.dart from catalog/model-tiers.json.
// Do not edit: edit the catalog file and run the tool.

/// The model-tiers table this SDK was released with.
const bundledModelTiersJson = r\'\'\'
$json
\'\'\';
''');
  print('lib/src/model_tiers_table.dart written');
}
